INSERT INTO orders (
    order_no, user_id, total_amount, actual_amount, shipping_fee, discount_amount,
    status, payment_method, payment_time, transaction_id, shipping_address, receiver_name,
    receiver_phone, remark
) VALUES (
    #{orderNo}, #{userId}, #{totalAmount}, #{actualAmount}, #{shippingFee}, #{discountAmount},
    #{status}, #{paymentMethod}, #{paymentTime}, #{transactionId}, #{shippingAddress}, #{receiverName},
    #{receiverPhone}, #{remark}
)

INSERT INTO order_item (
    order_id, product_id, product_name, product_image, price, quantity, total_price
) VALUES (
    #{orderId}, #{productId}, #{productName}, #{productImage}, #{price}, #{quantity}, #{totalPrice}
)
